def value(x):
    z = [max(-6.0, min(6.0, (x[i] - MU[i]) / SD[i])) for i in range(len(x))]
    h1 = [math.tanh(B1[j] + sum(z[CI[k]] * W1[k][j] for k in range(len(CI)))) for j in range(len(B1))]
    h2 = [math.tanh(B2[j] + sum(h1[k] * W2[k][j] for k in range(len(h1)))) for j in range(len(B2))]
    logit = 0.0
    for o in range(len(B3)):
        s = B3[o] + sum(h2[k] * W3[k][o] for k in range(len(h2)))
        if o == 0:
            logit += s
        else:
            sp = s if s > 20 else math.log1p(math.exp(s))
            logit += SIGN[o - 1] * sp * z[MI[o - 1]]
    return 1.0 / (1.0 + math.exp(-logit))


def turn():
    try:
        _turn()
    except Exception as ex:
        Debug.log('PYERR ' + type(ex).__name__ + ': ' + str(ex)[:300])


def _turn():
    t = Fight.turn
    if t <= 3:
        o0 = System.operations
        p = 0.0
        for _ in range(20):
            p = value(MU)
        o1 = System.operations
        acc = 0
        for i in range(10000):
            acc += i * 2
        o2 = System.operations
        Debug.log('SPIKE_T%d_eval_%d_loop10k_%d_max_%d_p%.4f' % (t, (o1 - o0) // 20, o2 - o1, System.maxOperations, p))
    e = Fight.getNearestEnemy()
    if e is None:
        return
    Me.moveToward(e)
    ws = Me.weapons
    if ws and Me.weapon != ws[0]:
        Me.setWeapon(ws[0])
    for _ in range(4):
        r = Me.useWeapon(e)
        if r is None or r <= 0:
            break
